import { Badge, CardDescription, CardHeader, CardTitle } from '@clossys/designer-ui';
import type { GalleryHeaderData } from './types';

/** The gallery title and its leaf count. Layer navigation belongs to the page's explorer module, not a chip row. */
export function GalleryHeader({ header }: { header: GalleryHeaderData }) {
  return <CardHeader className="px-0">
    <CardTitle role="heading" aria-level={1} className="text-xl">{header.title}</CardTitle>
    <CardDescription className="max-w-(--measure)">{header.description}</CardDescription>
    {header.notice && <CardDescription><Badge variant="outline">{header.notice}</Badge></CardDescription>}
  </CardHeader>;
}

import { CardDescription, CardGrid, CardTitle } from '@clossys/designer-ui';
import { LeafCard } from './LeafCard';
import type { GalleryGroupData } from './types';

/** An L1 or L2 group: an anchored heading and its leaf cards, one per row (an L1 over L2 groups carries only the heading). */
export function GroupSection({ group, unit }: { group: GalleryGroupData; unit: readonly [string, string] }) {
  const heading = `${group.id}-heading`;
  return <section id={group.id} aria-labelledby={heading}>
    <CardTitle id={heading} role="heading" aria-level={group.level + 2}>{group.label}</CardTitle>
    {group.cards.length > 0 && <>
      <CardDescription>{group.cards.length} {group.cards.length === 1 ? unit[0] : unit[1]}</CardDescription>
      <CardGrid className="grid-cols-1 pt-3" data-layout="list">
        {group.cards.map(card => <LeafCard key={card.key} card={card} />)}
      </CardGrid>
    </>}
  </section>;
}

import { CardContent, CardTitle, Separator } from '@clossys/designer-ui';
import { GroupSection } from './GroupSection';
import type { GalleryLayerData } from './types';

/** An L0 layer: an anchored heading over its groups. */
export function LayerSection({ layer, unit }: { layer: GalleryLayerData; unit: readonly [string, string] }) {
  const heading = `${layer.id}-heading`;
  return <section id={layer.id} aria-labelledby={heading}>
    <CardTitle id={heading} role="heading" aria-level={2} className="text-lg">{layer.label}</CardTitle>
    <Separator className="my-3" />
    <CardContent className="flex flex-col gap-8 px-0">
      {layer.groups.map(group => <GroupSection key={group.id} group={group} unit={unit} />)}
    </CardContent>
  </section>;
}

import { Badge, Card, CardContent, CardDescription, CardHeader, CardTitle, LinkButton, SpecimenFrame } from '@clossys/designer-ui';
import type { GalleryCardData } from './types';

/**
 * One L3 leaf as a full-width row: a view-only specimen thumbnail (or text excerpt), the name,
 * the pinned version and one status signal. The whole card is the link.
 */
export function LeafCard({ card }: { card: GalleryCardData }) {
  return <Card size="sm" className="relative flex-row items-center" data-gallery-leaf={card.key}>
    <CardContent className="w-28 shrink-0 pr-0 sm:w-44">
      {card.specimenSrc
        ? <SpecimenFrame title={`${card.name} specimen`} src={card.specimenSrc} />
        : card.excerpt?.length
          ? <CardDescription className="line-clamp-4 text-xs break-words">{card.excerpt.join(' ')}</CardDescription>
          : <Badge variant="outline">{card.specimenStatus?.label ?? 'No specimen'}</Badge>}
    </CardContent>
    <CardHeader className="min-w-0 flex-1">
      <CardTitle>
        <LinkButton href={card.href} variant="link" className="h-auto p-0 text-left text-base whitespace-normal after:absolute after:inset-0">{card.name}</LinkButton>
      </CardTitle>
      <CardDescription className="flex flex-wrap items-center gap-2">
        {card.version !== undefined && <Badge variant="ghost">v{card.version}</Badge>}
        <Badge variant={card.statusTone}>{card.statusLabel}</Badge>
      </CardDescription>
    </CardHeader>
  </Card>;
}

import { CardContent } from '@clossys/designer-ui';
import { GalleryHeader } from './GalleryHeader';
import { LayerSection } from './LayerSection';
import type { AgentGalleryInput } from './types';

export type { AgentGalleryInput, GalleryCardData, GalleryGroupData, GalleryHeaderData, GalleryLayerData, GalleryTone } from './types';

/**
 * `sections.studio.agent-gallery`: any agent's gallery. L0-L2 anchored sections in one vertical
 * scroll, L3 leaves as a vertical list of view-only link cards, one per row. The page body is the
 * frame's column, so the section adds no outer card. Reads only its `gallery` input.
 */
export default function AgentGallerySection({ gallery }: { gallery: AgentGalleryInput }) {
  return <section data-studio-section="agent-gallery" aria-label={gallery.header.title}>
    <GalleryHeader header={gallery.header} />
    <CardContent className="flex flex-col gap-10 px-0 pt-6">
      {gallery.layers.map(layer => <LayerSection key={layer.id} layer={layer} unit={gallery.unit} />)}
    </CardContent>
  </section>;
}

